public fun lookup(c: Char): Boolean {
    if (false) {
        check(!c.isAscii())
    }
    return when (c.code.toUInt() shr 8) {
        0u -> WHITESPACE_MAP[c.code and 0xff] and 1u.toUByte() != 0u.toUByte()
        22u -> c.code.toUInt() == 0x1680u
        32u -> WHITESPACE_MAP[c.code and 0xff] and 2u.toUByte() != 0u.toUByte()
        48u -> c.code.toUInt() == 0x3000u
        else -> false
    }
}
